var centerX = 0.5 + (latitudeBands / 5) * squareSize;
var centerY = 0.5 + (longitudeBands / 2.65) * squareSize;
var radius = 0.95 * (latitudeBands * squareSize);
var steps = rand;

function pol() {
	for (h = 0; h <= 85; h++) {
		var pl = [];
		for (i = 0; i <= steps; i++) {
			var cx = (h * 5) - centerX + radius * Math.cos((2 * Math.PI * i) / steps);
			var cy = (h * 5) - centerY + radius * Math.sin((2 * Math.PI * i) / steps);
			var p = {
				id: 0,
				x: cx,
				y: cy
			};
			pl.push(p);
		}
		polyLineClick.push(pl);
	}

}

